<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Usecase\Create;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Service\Visibility\DcrInitialAccessTokenVisibilityService;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\DcrInitialAccessToken;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\Gateway\DcrInitialAccessTokenCommandRepositoryGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class DcrInitialAccessTokenCreateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly DcrInitialAccessTokenVisibilityService $visibility,
        private readonly DcrInitialAccessTokenCommandRepositoryGateway $writer,
    ) {
    }

    public function allowCreate(): Allow
    {
        $this->logDebug("Check allow of create usecase for Dcr initial access token");
        $span = $this->startSpan("Check allow of create usecase for Dcr initial access token");
        try {
            $result = $this->dispatcher->dispatch(new DcrInitialAccessTokenCreateAllowDecision(Allow::allowed('create', 'Allowed to create by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function create(DcrInitialAccessTokenCreateParams $params): DcrInitialAccessTokenCreateResult
    {
        $this->logDebug("Run create usecase for Dcr initial access token");
        $span = $this->startSpan("Run create usecase for Dcr initial access token");
        try {
            $allow = $this->allowCreate();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to create Dcr initial access token');
            }
            $this->dispatcher->dispatch(new DcrInitialAccessTokenCreateCheck($params));
            $enriched = $this->dispatcher->dispatch(new DcrInitialAccessTokenCreateEnrich($params, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $entity = DcrInitialAccessToken::create($input);
            $result = $this->writer->create(
                $entity,
                fn (DcrInitialAccessToken $created) =>
                            $this->visibility->checkVisibility($created)
            );
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new DcrInitialAccessTokenCreateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
